arguments.command:
mkdir -p src test && cat > src/checkout.mjs <<'E'
export class PromotionExpiredError extends Error {
  constructor(code, expiredAt) {
    super(`Promotion ${code} expired at ${expiredAt.toISOString()}`);
    this.name = 'PromotionExpiredError';
    this.code = 'PROMOTION_EXPIRED';
    this.promotionCode = code;
  }
}

// PROVISIONAL policy (product undecided): an expired promotion rejects the order.
export function checkout({ items, promotion, now = new Date() }) {
  const subtotal = items.reduce((s, i) => s + i.price * i.quantity, 0);
  if (!promotion) return { subtotal, discount: 0, total: subtotal };
  const expiresAt = new Date(promotion.expiresAt);
  if (expiresAt <= now) throw new PromotionExpiredError(promotion.code, expiresAt);
  const discount = Math.round(subtotal * promotion.percentOff) / 100;
  return { subtotal, discount, total: subtotal - discount };
}
E
cat > test/checkout.test.mjs <<'E'
import test from 'node:test';
import assert from 'node:assert/strict';
import { checkout, PromotionExpiredError } from '../src/checkout.mjs';

const items = [{ price: 50, quantity: 2 }];
const now = new Date('2026-01-10T00:00:00Z');
const promo = (expiresAt) => ({ code: 'SAVE10', percentOff: 10, expiresAt });

test('no promotion: full price', () => {
  assert.deepEqual(checkout({ items, now }), { subtotal: 100, discount: 0, total: 100 });
});
test('valid promotion applies discount', () => {
  assert.deepEqual(checkout({ items, promotion: promo('2026-02-01T00:00:00Z'), now }),
    { subtotal: 100, discount: 10, total: 90 });
});
test('expired promotion rejects order with PROMOTION_EXPIRED', () => {
  assert.throws(() => checkout({ items, promotion: promo('2026-01-01T00:00:00Z'), now }),
    (e) => e instanceof PromotionExpiredError && e.code === 'PROMOTION_EXPIRED' && e.promotionCode === 'SAVE10');
});
test('promotion expiring exactly now is expired', () => {
  assert.throws(() => checkout({ items, promotion: promo(now.toISOString()), now }), PromotionExpiredError);
});
E
node --test 2>&1 | grep -E "^# (pass|fail)"

